CREATE POLICY "Allow all for anon" ON quotations FOR ALL USING (true) WITH CHECK (true);
CREATE POLICY "Allow all for anon" ON invoices FOR ALL USING (true) WITH CHECK (true);
CREATE POLICY "Allow all for anon" ON jobs FOR ALL USING (true) WITH CHECK (true);
CREATE POLICY "Allow all for anon" ON driver_submissions FOR ALL USING (true) WITH CHECK (true);
CREATE POLICY "Allow all for anon" ON rent_to_own_agreements FOR ALL USING (true) WITH CHECK (true);
CREATE POLICY "Allow all for anon" ON rent_to_own_payments FOR ALL USING (true) WITH CHECK (true);
CREATE POLICY "Allow all for anon" ON payment_categories FOR ALL USING (true) WITH CHECK (true);
